package escuela.admin.dto;
import escuela.cobranza.dto.request.PoliticaRecargoRequest;import escuela.cobranza.dto.response.PoliticaRecargoResponse;import escuela.cobranza.entity.*;import jakarta.validation.constraints.*;import lombok.Getter;import lombok.Setter;import java.math.BigDecimal;
@Getter @Setter public class PoliticaRecargoForm{
 @NotNull private Long institucionId;@NotNull private Long conceptoCobroId;@NotNull private ModalidadBeca modalidad=ModalidadBeca.PORCENTAJE;private BigDecimal porcentaje;private BigDecimal montoFijo;@Size(max=3)private String moneda;@Min(0)@Max(365)private int diasGracia=5;@NotNull private PeriodicidadRecargo periodicidad=PeriodicidadRecargo.UNICA;@NotNull private TipoLimiteRecargo tipoLimite=TipoLimiteRecargo.PORCENTAJE_ORIGINAL;private BigDecimal valorLimite=new BigDecimal("20");private boolean generacionAutomatica=true;private boolean activo=true;private Long version;
 public PoliticaRecargoRequest request(){return new PoliticaRecargoRequest(conceptoCobroId,modalidad,modalidad==ModalidadBeca.PORCENTAJE?porcentaje:null,modalidad==ModalidadBeca.MONTO_FIJO?montoFijo:null,modalidad==ModalidadBeca.MONTO_FIJO?moneda:null,diasGracia,periodicidad,tipoLimite,tipoLimite==TipoLimiteRecargo.SIN_LIMITE?null:valorLimite,generacionAutomatica,activo,version);}
 public static PoliticaRecargoForm desde(PoliticaRecargoResponse r){PoliticaRecargoForm f=new PoliticaRecargoForm();f.institucionId=r.institucionId();f.conceptoCobroId=r.conceptoCobroId();f.modalidad=r.modalidad();f.porcentaje=r.porcentaje();f.montoFijo=r.montoFijo();f.moneda=r.moneda();f.diasGracia=r.diasGracia();f.periodicidad=r.periodicidad();f.tipoLimite=r.tipoLimite();f.valorLimite=r.valorLimite();f.generacionAutomatica=r.generacionAutomatica();f.activo=r.activo();f.version=r.auditoria().version();return f;}
}
